let w;
let pg;

preload = () => {loadmyshader();}

function setup() {
	w = max(windowWidth, windowHeight);
	createCanvas(w, w, WEBGL);
	pg = createGraphics(w, w, WEBGL);
	//drawing the initial image
	pg.noStroke();
	pg.fill(255);
	pg.background(0)

	pg.square(-w/8, -w/8, w/4)
	pg.square(-w/16, w/6, w/8)
}

function draw() {
	pg.shader(theShader);//use shader
	theShader.setUniform("u_resolution", [width, height]); //shader variables
	theShader.setUniform("tex0", pg);
	pg.quad(-1, -1, 1, -1, 1, 1, -1, 1); //draw shader output onto pg
	image(pg, -w/2, -w/2) //draw pg onto the canvas
}

// === Tab: Shader ===
let theShader;
function loadmyshader(){
	theShader = createShader(vert, frag);
}

const vert = `
	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	void main() {
		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

		gl_Position = positionVec4;
	}
`;

const frag = `
#ifdef GL_ES
precision mediump float;
#endif

#define color_step 5.

uniform vec2 u_resolution;
uniform sampler2D tex0;

void main()
{
		vec2 uv = gl_FragCoord.xy/u_resolution;
		uv*=0.5;
		uv.y=1.-uv.y;
		float px = 1.5/u_resolution.x;

		vec3 sum = vec3(0.);
		for(float i=-1.; i<=1.; i++){
			for(float j=-1.; j<=1.; j++){
				sum += texture2D(tex0,uv+vec2(i, j)*px).rgb;
			}
		}
		sum /= 9.;

    gl_FragColor = vec4(sum, 1.);
}
`;

